  font-size: 20px;
  margin-bottom: 4px;
}

.welcome p {
  color: #888;
  font-size: 14px;
}

.user-info {
  display: flex;
  align-items: center;
  gap: 20px;
}

.points-badge {
  background: linear-gradient(135deg, #ffd89b, #c7e9fb);
  padding: 8px 16px;
  border-radius: 30px;
  color: #333;
  font-weight: 600;
}

.points-badge i {
  color: #ffc107;
  margin-right: 6px;
}

.avatar i {
  font-size: 40px;
  color: #667eea;
}

/* 商品区域 */
.goods-section, .history-section {
  background: white;
  margin: 0 30px 30px;
