  justify-content: center;
}

.goods-icon i {
  font-size: 28px;
  color: white;
}

.goods-info {
  flex: 1;
}

.goods-info h4 {
  margin: 0 0 6px;
  font-size: 16px;
}

.goods-info p {
  margin: 0 0 12px;
  font-size: 13px;
  color: #888;
